<script setup>
import {ref,computed,onMounted,nextTick} from 'vue'
import {Phone,MessageCircle,MousePointer2,ArrowDownRight,ArrowLeft,RefreshCw,X,Users,BarChart3} from 'lucide-vue-next'
import {voiceApi as api} from '../voice/operations'
const props=defineProps({campaignId:Number,campaigns:{type:Array,default:()=>[]}})
const emit=defineEmits(['back'])
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const start=new Date(today+'T12:00:00Z');start.setUTCDate(start.getUTCDate()-29)
const draft=ref({campaign_id:props.campaignId||'',from:start.toISOString().slice(0,10),to:today})
const filters=ref({...draft.value}),data=ref(null),error=ref(''),busy=ref(false),drill=ref(null),rows=ref(null),detail=ref(null),dialog=ref(null),detailError=ref(''),detailBusy=ref(false),phone=ref('')
const status={pending:'Pendente',dialing:'Chamando',answered:'Atendida',completed:'Atendida / encerrada',no_answer:'Não atendeu',busy:'Ocupado',failed:'Falha',unknown:'Sem confirmação',cancelled:'Cancelada',sending:'Preparando envio',accepted:'Aceita pelo provedor',queued:'Na fila do provedor',scheduled:'Agendada',sending_provider:'Enviando',sent:'Enviada',delivered:'Entregue',read:'Lida',undelivered:'Não entregue',received:'Recebida'}
const attribution={context:'Vínculo com a mensagem original',single_journey:'Inferida: única jornada nos últimos 7 dias',unattributed:'Sem vínculo seguro com uma jornada'}
const definitions={calls:['Chamadas feitas','Tentativas iniciadas pela telefonia'],answered:['Atendidas','Atendimento técnico confirmado'],no_answer:['Não atenderam','Encerradas sem atendimento'],call_failed:['Falhas de chamada','Inclui falhas antes da discagem'],call_other:['Outros resultados','Ocupadas, canceladas ou em andamento'],dispatches:['Mensagens disparadas','Solicitações de envio, exceto canceladas'],delivered:['Entregues','Inclui mensagens já lidas'],read:['Lidas','Leitura confirmada pelo WhatsApp'],message_failed:['Falhas de mensagem','Falha ou entrega recusada'],message_pending:['Sem entrega confirmada','Enviadas, pendentes ou sem confirmação'],replies:['Respostas recebidas','Inclui respostas por botão'],button_clicks:['Cliques em botões','Botões de resposta identificados'],unattributed:['Respostas sem jornada','Atribuição não confirmada']}
const mainMetrics=['calls','answered','no_answer','dispatches','delivered','read','message_failed','replies','button_clicks']
const title=computed(()=>props.campaigns.find(c=>c.id===Number(filters.value.campaign_id))?.name||'Todas as jornadas de voz e WhatsApp')
const summary=computed(()=>data.value?.summary||{})
const maxDaily=computed(()=>Math.max(1,...(data.value?.timeline||[]).map(x=>Math.max(x.calls,x.dispatches,x.replies)) ))
const format=n=>Number(n||0).toLocaleString('pt-BR')
const percent=(n,d)=>d?Math.round(n/d*100)+'%':'—'
const stamp=x=>x?new Date(/[Zz]|[+-]\d\d:\d\d$/.test(x)?x:x.replace(' ','T')+'Z').toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—'
const date=x=>x.split('-').reverse().slice(0,2).join('/')
const params=o=>new URLSearchParams(Object.entries(o).filter(([,v])=>v!==''&&v!=null)).toString()
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const result=await api('/journey-reports?'+params(draft.value));data.value=result;filters.value={...draft.value};drill.value=null;rows.value=null;phone.value=''}
async function details(metric,extra={}){drill.value={metric,page:1,...extra};phone.value='';await loadRows();await nextTick();document.getElementById('journey-report-details')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function loadRows(){rows.value=null;rows.value=await api('/journey-reports/details?'+params({...filters.value,...drill.value,phone:phone.value}))}
async function selectJourney(id){if(id===null){await details('unattributed');return}draft.value.campaign_id=id;await load()}
async function openRecord(row){detail.value={row};detailError.value='';dialog.value.showModal();detailBusy.value=true;try{detail.value={row,...await api('/journey-reports/records/'+row.kind+'/'+row.id)}}catch(e){detailError.value=e.message}finally{detailBusy.value=false}}
onMounted(()=>run(load))
</script>

<template>
<section class="journey-dashboard" :aria-busy="busy">
 <div class="jd-heading"><div><span class="eyebrow">RESULTADOS QUE VIRAM PRÓXIMOS PASSOS</span><h2>Dashboard da jornada</h2><p>{{title}}</p></div><button v-if="campaignId" class="secondary" @click="emit('back')"><ArrowLeft :size="16"/> Voltar ao fluxo</button></div>
 <form class="jd-filter" @submit.prevent="run(load)">
  <label>Jornada<select aria-label="Jornada do dashboard" v-model="draft.campaign_id"><option value="">Todas as jornadas de voz e WhatsApp</option><option v-for="c in campaigns" :key="c.id" :value="c.id">{{c.name}}</option></select></label>
  <label>De<input aria-label="Dashboard de" type="date" v-model="draft.from" required min="2020-01-01"></label><label>Até<input aria-label="Dashboard até" type="date" v-model="draft.to" required :min="draft.from"></label>
  <button class="primary" :disabled="busy"><RefreshCw :size="16"/> {{busy?'Atualizando…':'Aplicar filtros'}}</button>
 </form>
 <p v-if="error" role="alert" class="jd-error">{{error}}</p>
 <template v-if="data">
 <div class="jd-meta"><span>{{data.filters.from.split('-').reverse().join('/')}} — {{data.filters.to.split('-').reverse().join('/')}} · Horário de São Paulo</span><span>Atualizado {{stamp(data.generated_at)}}</span></div>
 <div class="jd-kpis">
  <button v-for="key in mainMetrics" :key="key" class="jd-kpi" :class="{selected:drill?.metric===key}" :disabled="busy" @click="run(()=>details(key))" :aria-label="definitions[key][0]+': '+format(summary[key])+'. Ver detalhes'">
   <span class="jd-kpi-label"><component :is="key==='button_clicks'?MousePointer2:['calls','answered','no_answer'].includes(key)?Phone:MessageCircle" :size="16"/>{{definitions[key][0]}}<ArrowDownRight :size="15"/></span>
   <strong>{{format(summary[key])}}</strong><small>{{definitions[key][1]}}</small>
  </button>
 </div>
 <div class="jd-rates"><span><Users :size="16"/> {{format(summary.called_contacts)}} contatos chamados</span><span>{{format(summary.answered_contacts)}} contatos atendidos</span><span>{{format(summary.human_contacts)}} conversas humanas confirmadas</span><span>{{format(summary.reply_contacts)}} pessoas responderam</span><span>{{format(summary.button_contacts)}} pessoas clicaram</span></div>
 <div class="jd-charts">
  <article class="jd-card"><header><div><span class="eyebrow">VOZ</span><h3>Resultado das chamadas</h3></div><span class="jd-rate">{{percent(summary.answered,summary.calls)}}<small>atendimento</small></span></header>
   <button v-for="[key,color] in [['answered','green'],['no_answer','gold'],['call_failed','red'],['call_other','slate']]" :key="key" class="jd-bar-row" :disabled="busy" @click="run(()=>details(key))"><span>{{definitions[key][0]}}</span><strong>{{format(summary[key])}}</strong><div class="jd-track"><i :class="color" :style="{width:(100*summary[key]/Math.max(1,summary.calls,summary.call_failed))+'%'}"/></div></button>
   <p class="jd-hint">Atendimento pela telefonia pode incluir caixa postal. A tabulação confirma se houve conversa humana.</p>
  </article>
  <article class="jd-card"><header><div><span class="eyebrow">WHATSAPP</span><h3>Da mensagem à leitura</h3></div><span class="jd-rate">{{percent(summary.delivered,summary.dispatches)}}<small>entrega</small></span></header>
   <button v-for="[key,color] in [['dispatches','slate'],['delivered','green'],['read','gold'],['message_failed','red'],['message_pending','slate']]" :key="key" class="jd-bar-row" :disabled="busy" @click="run(()=>details(key))"><span>{{definitions[key][0]}}</span><strong>{{format(summary[key])}}</strong><div class="jd-track"><i :class="color" :style="{width:(100*summary[key]/Math.max(1,summary.dispatches))+'%'}"/></div></button>
   <p class="jd-hint">Entregues e lidas são etapas acumuladas: uma mensagem lida também está entre as entregues. Falta de confirmação não significa falha.</p>
  </article>
 </div>
 <article class="jd-card jd-timeline"><header><div><span class="eyebrow">EVOLUÇÃO</span><h3>Atividade ao longo do período</h3></div><div class="jd-legend"><span><i class="gold"/> Chamadas</span><span><i class="green"/> Mensagens</span><span><i class="slate"/> Respostas</span></div></header>
  <div class="jd-timeline-scroll"><div class="jd-days" :style="{minWidth:Math.max(500,data.timeline.length*29)+'px'}"><div v-for="day in data.timeline" :key="day.day" class="jd-day"><div class="jd-day-bars"><button v-for="[key,color] in [['calls','gold'],['dispatches','green'],['replies','slate']]" :key="key" :class="color" :style="{height:Math.max(2,day[key]/maxDaily*130)+'px'}" :disabled="busy||!day[key]" :title="date(day.day)+' · '+definitions[key][0]+': '+day[key]" :aria-label="day.day+' '+definitions[key][0]+': '+day[key]" @click="run(()=>details(key,{day:day.day}))"/></div><span>{{date(day.day)}}</span></div></div></div>
  <p class="jd-hint">Clique numa barra para abrir os registros daquele dia. Chamadas: início da tentativa; mensagens: solicitação de envio; respostas: recebimento.</p>
 </article>
 <article class="jd-card"><header><div><span class="eyebrow">INTERAÇÕES</span><h3>Qual botão foi escolhido?</h3></div><MousePointer2 :size="24"/></header>
  <div v-if="data.buttons.length" class="jd-button-ranking"><button v-for="b in data.buttons" :key="b.button_id+':'+b.button_label" :disabled="busy" @click="run(()=>details('button_clicks',{button_id:b.button_id,button_label:b.button_label}))"><span><strong>{{b.button_label}}</strong><small>ID: {{b.button_id}}</small></span><span class="jd-button-count">{{format(b.clicks)}} cliques<small>{{format(b.contacts)}} pessoas</small></span><ArrowDownRight :size="18"/></button></div>
  <div v-else class="jd-empty"><MousePointer2 :size="26"/><strong>Nenhum clique confirmado neste período</strong><p>Os botões aparecem aqui quando o cliente escolhe uma resposta vinculada à mensagem enviada.</p></div>
  <p class="jd-hint">Exibição do botão não conta como clique. Botões que abrem links não têm rastreamento neste conector. Até 100 combinações de botão e título; o indicador de cliques contém o total.</p>
 </article>
 <article v-if="!filters.campaign_id" class="jd-card"><header><div><span class="eyebrow">COMPARATIVO</span><h3>Resultados por jornada</h3></div><BarChart3 :size="22"/></header><div class="jd-scroll"><table><thead><tr><th>Jornada</th><th>Chamadas</th><th>Atendidas</th><th>Não atenderam</th><th>Mensagens</th><th>Entregues</th><th>Lidas</th><th>Falhas WhatsApp</th><th>Respostas</th><th>Botões</th></tr></thead><tbody><tr v-for="j in data.journeys" :key="j.id||'unattributed'"><td><button class="jd-link" :disabled="busy" @click="run(()=>selectJourney(j.id))">{{j.name}}</button></td><td v-for="key in ['calls','answered','no_answer','dispatches','delivered','read','message_failed','replies','button_clicks']" :key="key">{{format(j[key])}}</td></tr></tbody></table></div></article>
 <div class="jd-attribution"><p>Respostas sem referência à mensagem são atribuídas somente quando existe uma única jornada no mesmo número nos 7 dias anteriores. Neste período: <strong>{{data.attribution.inferred}} inferidas</strong><template v-if="!filters.campaign_id"> e <button class="jd-link" @click="run(()=>details('unattributed'))">{{data.attribution.unattributed}} sem jornada atribuída</button></template>.</p><p>Os indicadores contam eventos, não pessoas. Os totais de pessoas são distintos dentro do período. Apenas chamadas e mensagens reais; simulações ficam no histórico de testes.</p></div>
 <section v-if="drill" id="journey-report-details" class="jd-card jd-details"><header><div><span class="eyebrow">DETALHAMENTO</span><h3>{{definitions[drill.metric][0]}}</h3><p v-if="drill.day">Dia {{drill.day.split('-').reverse().join('/')}}</p><p v-if="drill.button_id">Botão: {{drill.button_label}} · {{drill.button_id}}</p></div><button class="secondary" @click="drill=null;rows=null" aria-label="Fechar detalhamento"><X :size="18"/></button></header>
  <form class="jd-search" @submit.prevent="run(async()=>{drill.page=1;await loadRows()})"><label>Filtrar telefone<input v-model="phone" aria-label="Telefone no detalhamento" placeholder="DDD ou número" pattern="[+0-9]{2,20}"></label><button class="secondary" :disabled="busy">Buscar</button></form>
  <div v-if="rows" class="jd-scroll"><table><thead><tr><th>Contato / jornada</th><th>Resultado</th><th>{{rows.rows.data[0]?.kind==='calls'?'Ligação':'Mensagem / interação'}}</th><th>Quando</th><th>Detalhes</th></tr></thead><tbody><tr v-for="r in rows.rows.data" :key="r.id"><td><strong>{{r.contact_name}}</strong><small>{{r.destination||(r.direction==='inbound'?r.from_number:r.to_number)}}</small><small>{{r.campaign_name||'Sem jornada atribuída / avulsa'}}</small></td><td><span class="jd-status" :class="r.status">{{status[r.status]||r.status}}</span><small v-if="r.error_code">Erro {{r.error_code}}</small></td><td v-if="r.kind==='calls'">{{r.method==='programmable_voice'?'Twilio API':'SIP'}} · {{r.bill_seconds}} s<small>{{r.disposition_label||'Sem tabulação'}}</small><small>Origem: {{r.caller_id}}</small></td><td v-else><span class="jd-message">{{r.body||'Template do provedor'}}</span><small v-if="r.button_id">Botão: {{r.button_label}} · {{r.button_id}}</small><small v-if="r.reply_attribution">{{attribution[r.reply_attribution]}}</small><small>{{r.provider==='qr'?'QR Code':'Twilio API'}}</small></td><td>{{stamp(r.started_at||r.created_at)}}</td><td><button class="secondary" :aria-label="'Ver detalhes de '+r.contact_name" @click="openRecord(r)">Ver detalhes</button></td></tr></tbody></table><div v-if="!rows.rows.data.length" class="jd-empty">Nenhum registro para este indicador e filtro.</div></div>
  <footer v-if="rows" class="jd-pagination"><span>{{format(rows.rows.total)}} registros · página {{rows.rows.current_page}} de {{rows.rows.last_page}}</span><div><button class="secondary" :disabled="busy||rows.rows.current_page<=1" @click="run(async()=>{drill.page--;await loadRows()})">Anterior</button><button class="secondary" :disabled="busy||rows.rows.current_page>=rows.rows.last_page" @click="run(async()=>{drill.page++;await loadRows()})">Próxima</button></div></footer>
 </section>
 </template>
 <dialog ref="dialog" class="jd-dialog" aria-labelledby="jd-detail-title"><template v-if="detail"><header><div><span class="eyebrow">REGISTRO DA JORNADA</span><h3 id="jd-detail-title">{{detail.row.contact_name}}</h3></div><button class="secondary" @click="dialog.close()" aria-label="Fechar registro"><X :size="18"/></button></header><p v-if="detailBusy">Carregando detalhes…</p><p v-if="detailError" role="alert">{{detailError}}</p><template v-if="detail.record"><p>{{detail.row.campaign_name||'Sem jornada atribuída'}}</p><span class="jd-status">{{status[detail.record.status]||detail.record.status}}</span><dl><dt>ID do registro</dt><dd>{{detail.record.id}}</dd><dt>Criado em</dt><dd>{{stamp(detail.record.created_at)}}</dd><template v-if="detail.row.kind==='calls'"><dt>Início / término</dt><dd>{{stamp(detail.record.started_at)}} / {{stamp(detail.record.ended_at)}}</dd><dt>Atendimento</dt><dd>{{stamp(detail.record.answered_at)}}</dd><dt>Conversa humana</dt><dd>{{detail.record.human_confirmed===true?'Confirmada pela tabulação':detail.record.human_confirmed===false?'Não confirmada pela tabulação':'Sem tabulação confirmando'}}</dd><dt>Retorno técnico</dt><dd>{{detail.record.dial_status||'—'}} · {{detail.record.cause||'—'}}</dd></template><template v-else><dt>Origem → destino</dt><dd>{{detail.record.from_number}} → {{detail.record.to_number}}</dd><dt>Última atualização</dt><dd>{{stamp(detail.record.updated_at)}}</dd><dt v-if="detail.record.reply_attribution">Atribuição</dt><dd v-if="detail.record.reply_attribution">{{attribution[detail.record.reply_attribution]}}</dd></template></dl><blockquote v-if="detail.record.body">{{detail.record.body}}</blockquote><template v-if="detail.record.interactive?.buttons"><h4>Botões enviados</h4><p v-for="b in detail.record.interactive.buttons" :key="b.id">{{b.label}} <small>{{b.id}} · {{b.type==='reply'?'Resposta':'Link sem rastreamento'}}</small></p></template><p v-if="detail.record.button_id"><strong>Botão escolhido:</strong> {{detail.record.button_label}} · {{detail.record.button_id}}</p><div v-if="detail.original_message"><h4>Mensagem original</h4><blockquote>{{detail.original_message.body||'Template do provedor'}}</blockquote></div><h4>{{detail.row.kind==='calls'?'Histórico de tabulação':'Confirmações registradas'}}</h4><p v-for="(e,i) in detail.events" :key="i">{{stamp(e.created_at)}} · {{e.label||status[e.status]||e.status}}<small v-if="e.notes">{{e.notes}}</small></p><p v-if="!detail.events?.length" class="jd-hint">Nenhum evento adicional registrado. Confirmações antigas de QR podem ter apenas o estado atual.</p><template v-if="detail.replies?.length"><h4>Respostas a esta mensagem</h4><p v-for="r in detail.replies" :key="r.id">{{stamp(r.created_at)}} · {{r.body}}<small v-if="r.button_id">Botão: {{r.button_label}} · {{r.button_id}}</small></p></template></template></template></dialog>
</section>
</template>

<style scoped>
