tom:22px}.jd-card h3,.jd-dialog h3{margin:6px 0 0;font-size:19px;letter-spacing:-.5px}.jd-card header .eyebrow,.jd-heading .eyebrow{font-size:9px}.jd-rate{font-size:26px;color:#52836a;text-align:right}.jd-rate small{display:block;font-size:10px;color:#8a917d;margin-top:5px}.jd-bar-row{display:grid;grid-template-columns:1fr auto;width:100%;background:transparent;border:0;text-align:left;padding:10px 0;color:inherit;gap:8px;cursor:pointer;font-size:12px}.jd-bar-row strong{font-size:13px}.jd-track{grid-column:1/-1;height:8px;background:#f2f3ec;border-radius:5px;overflow:hidden}.jd-track i{display:block;height:100%;border-radius:5px;min-width:0}.gold{background:#c79a37}.green{background:#568c70}.red{background:#bf7370}.slate{background:#8395a2}.jd-hint{font-size:11px;line-height:1.7;color:#838a78;margin:18px 0 0}.jd-legend{display:flex;gap:14px;flex-wrap:wrap;font-size:11px;color:#7c836f}.jd-legend span{display:flex;align-items:center;gap:6px}.jd-legend i{width:8px;height:8px;border-radius:2px}.jd-timeline-scroll,.jd-scroll{overflow:auto}.jd-days{display:flex;align-items:flex-end;gap:5px;padding-top:12px}.jd-day{flex:1;text-align:center}.jd-day-bars{height:140px;display:flex;align-items:flex-end;justify-content:center;gap:3px;border-bottom:1px solid #dce0d4}.jd-day-bars button{border:0;border-radius:3px 3px 0 0;min-width:5px;width:23%;max-width:19px;padding:0;cursor:pointer}.jd-day-bars button:disabled{opacity:.3}.jd-day>span{display:block;font-size:9px;color:#859078;margin-top:10px}.jd-button-ranking{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.jd-button-ranking button{display:flex;align-items:center;gap:14px;padding:18px;border:1px solid #e1e1d5;border-radius:12px;background:#fafaf6;text-align:left;color:inherit;cursor:pointer}.jd-button-ranking strong{font-size:13px}.jd-button-ranking small{display:block;font-size:10px;color:#7e8772;margin-top:6px}.jd-button-count{margin-left:auto;white-space:nowrap;font-size:14px;color:#a47c24}.jd-